using System;using System.Linq;
namespace IdleIntelligence.Core
{
 public sealed class TutorialDestination{public string Tab="hardware",Element="TapLab",Mode="",Title,Explanation,Requirement;}
 public static class TutorialNavigation
 {
  static bool Buy(GameState s,int i,long quantity)=>quantity>0&&i<(ChallengeRules.Current(s)?.ClassLimit??s.Hardware.Length)&&s.Credits.CompareTo(Game.HardwareCost(s,i,quantity))>=0;
  public static TutorialDestination Quote(GameState s){bool de=s.Settings.language=="de";string target=s.Story.target;var q=new TutorialDestination();if(s.Story.tutorial!="active"||target==null)return null;if(target=="name"||target=="prologue")return new TutorialDestination{Tab="story",Element=target=="name"?"StoryNameInput":"StoryContinue",Title=de?"KI benennen / Mira":"Name your AI / Mira"};int pending=target=="hardware"?0:((target=="research"&&!Game.IntroResearch(s)||target=="analysis")&&!s.Industry.discovered[1]?1:-1);if(pending>=0&&s.Settings.buyMode!="1"&&Buy(s,pending,1)&&!Buy(s,pending,SettingsRules.BuyQuantity(s,pending)))return new TutorialDestination{Tab="settings",Element="BuyMode-1",Title=de?"Kaufmenge wählen":"Choose purchase amount",Explanation=de?"Wechsle auf ×1, um die benötigte Hardware zu kaufen.":"Switch to ×1 to buy the required hardware."};
   switch(target){case "tap":q.Title=de?"2 · Erster Impuls":"2 · First impulse";q.Explanation=de?"Tippe auf das Labor für Credits. Halte gedrückt für mehrere Impulse.":"Tap the lab for credits. Hold down for repeated impulses.";break;
    case "hardware":bool ready=Buy(s,0,SettingsRules.BuyQuantity(s,0));q.Element=ready?"hardware-calculator":"TapLab";q.Title=ready?(de?"3 · Erste Hardware":"3 · First hardware"):(de?"3 · Credits verdienen":"3 · Earn credits");q.Explanation=ready?(de?"Kaufe deinen ersten Taschenrechner.":"Buy your first calculator."):(de?"Tippe auf den KI-Kern für die erste Hardware.":"Tap the AI core to afford your first hardware.");break;
    case "production":q.Element="Compute";q.Title=de?"4 · Nutzer und Compute":"4 · Users and compute";q.Explanation=de?"Hardware → Compute → Nutzer → Credits.":"Hardware → compute → users → credits.";break;
    case "credits":q.Element="Credits";q.Title=de?"5 · Credits sammeln":"5 · Collect credits";q.Explanation=de?"Warte auf reguläre Produktion oder nutze echte Taps bis 25 Credits.":"Wait for regular production or use real taps until you have 25 credits.";q.Requirement=s.Credits.CompareTo(ScientificNumber.From(Balance.TutorialCreditGoal))<0?(de?"Noch ":"")+Math.Ceiling(Balance.TutorialCreditGoal-s.Credits.ToDouble())+(de?" Credits.":" credits remaining."):null;break;
    case "training":q.Tab="training";q.Element="training-quality";q.Title=de?"6 · Training starten":"6 · Start training";q.Explanation=Game.IntroQuality(s)?(de?"Erstes Qualitätstraining: kostenlos, ":"First quality training: free, ")+Balance.IntroTrainingSeconds+(de?" Sekunden.":" seconds."):(de?"Trainiere Qualität für mehr Umsatz.":"Train quality to increase revenue.");q.Requirement=s.Training!=null?(de?"Ein Training läuft bereits.":"Training is already active."):s.Credits.CompareTo(Game.TrainingCost(s,"quality"))<0?(de?"Verdiene zuerst die angezeigten Credits.":"Earn the displayed Credits first."):null;break;
    case "research":case "analysis":if(!s.Industry.discovered[1]&&(target=="analysis"||!Game.IntroResearch(s))){bool sbc=Buy(s,1,SettingsRules.BuyQuantity(s,1));q.Element=sbc?"hardware-sbc":"TapLab";q.Title=target=="research"?(de?"7 · Forschung vorbereiten":"7 · Prepare research"):(de?"8 · Analyse vorbereiten":"8 · Prepare analysis");q.Explanation=sbc?(de?"Kaufe den Einplatinencomputer für den Laborzugang.":"Buy the single-board computer for lab access."):(de?"Sammle Credits für den Einplatinencomputer.":"Collect credits for the single-board computer.");}else if(target=="research"){q.Tab="research";q.Element="research-dataGeneration";q.Title=de?"7 · Forschung starten":"7 · Start research";q.Explanation=Game.IntroResearch(s)?(de?"Erste Datenerzeugung: kostenlos, ":"First Data Generation: free, ")+Balance.IntroResearchSeconds+(de?" Sekunden.":" seconds."):(de?"Starte Datenerzeugung im freien Labor.":"Start Data Generation in a free lab.");q.Requirement=Game.ResearchBlock(s,Game.ResearchIndex("dataGeneration"));}else{q.Tab="items";q.Mode="components";q.Element="analysis-hardware-short";q.Title=de?"8 · Analyse starten":"8 · Start analysis";q.Explanation=de?"Starte eine kurze Hardwareanalyse; alternativ zählt eine echte passive Komponentenbeschaffung.":"Start a short hardware analysis; a real passive component find also counts.";q.Requirement=MaterialAnalysis.Block(s,0);}break;
    case "crafting":q.Tab="items";q.Mode="blueprints";int recipe=Enumerable.Range(0,ItemBalance.Items.Length).Where(i=>s.Workshop.learned[i]&&Workshop.Prerequisite(s,i)).DefaultIfEmpty(Workshop.Index("quantum-chip")).First();q.Element="recipe-"+ItemBalance.Items[recipe].Id;q.Title=de?"9 · Erstes Item":"9 · First item";q.Explanation=de?"Starte einen regulären Item-Auftrag oder erhalte ein echtes Item.":"Start a regular item job or obtain a real item.";q.Requirement=Workshop.Quote(s,ItemBalance.Items[recipe].Id).Reason;break;
    case "prestige":q.Tab="prestige";q.Element="PrestigeReset";q.Title=de?"10 · Prestige vorbereiten":"10 · Prepare prestige";q.Explanation=de?"Öffne die Vorschau, sobald mindestens 1 INT wirklich beanspruchbar ist.":"Open the preview once at least 1 INT is genuinely claimable.";q.Requirement=PrestigeRules.Claim(s).CompareTo(ScientificNumber.One)<0?(de?"Noch kein INT beanspruchbar.":"No INT is claimable yet."):null;break;
   }return q;
  }
 }
}
